; Duke Skirmish — one open field, and the folder around it is the map.
;
; A map is a folder: this file, a preview.png beside it, and any .duke files of
; its own. The game finds it by its being under maps/ — nothing lists it.
;
; '#' is rock nothing walks through; anything else is open ground. Every position
; below is a CELL, counted from the top-left of Cells, so you can find it by eye.

Battlefield
  Name = clearing
  DisplayName = The Clearing
  Description = An open field with a spine of rock down the middle and ore in the corners.
  Players = 2
  ; A corner each, in the order the sides are added.
  Starts = [
    5 16,
    42 16,
  ]
  Cells = [
    "################################################",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#...................#######....................#",
    "#...................#######....................#",
    "#...................#######....................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#.....................####.....................#",
    "#.....................####.....................#",
    "#.....................####.....................#",
    "#.....................####.....................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
    "#..............................................#",
